          body: JSON.stringify({
            messages: [{ role: "user", content: prompt }],
            tier: "standard",
            org_id: body.org_id,
          }),
        })
      );

      if (!gatewayResp.ok) {
        return json({ error: `AI Gateway error: ${await gatewayResp.text()}` }, 502, origin);
